macros.\\ChangeNote:
%
  In Example~11, \PageRef{p.}{57}~\textit{ff.}, the text refers to the
  formula
  \[
  y = \left\{
    \begin{array}{@{}cl}
      \sqrt{(1 + p^{2})(1 + q^{2})} & \text{if $x = p/q$ in lowest terms,} \\
      x & \text{if $x$~is irrational.}
    \end{array}
  \right.
  \]
  The computer-generated \Fig{16} instead depicts the formula
  \[
  y = \left\{
    \begin{array}{@{}cl}
      \sqrt{(10 + p^{2})(10 + q^{2})} & \text{if $x = p/q$ in lowest terms,} \\
      x & \text{if $x$~is irrational,}
    \end{array}
  \right.
  \]
  which exhibits the same mathematical behavior, but better matches
  the hand-drawn diagram in the original.

macros.\\Chapter:
%
  \FlushRunningHeads
  \phantomsection
  \label{chapter:#1}
  \BookMark{0}{Chapter #1}%
  \renewcommand{\ChapNo}{#1}
  \thispagestyle{plain}
%
  \ifthenelse{\equal{}{}}{%
    \ifthenelse{\equal{#1}{IV}}{% Chapters IV, X get asymmetric heading
      \SetCenterHeads[LIMITS OF FUNCTIONS OF A]
      {POSITIVE INTEGRAL VARIABLE}%
    }{% Not Chapter IV
      \ifthenelse{\equal{#1}{X}}{%
        \SetCenterHeads[THE GENERAL THEORY OF THE LOGARITHMIC,]
        {EXPONENTIAL, AND CIRCULAR FUNCTIONS}%
      }{% Not Chapter X, but running head manually specified
        \SetCenterHeads{#2}%
      }%
    }%
  }{% Otherwise, use chapter title as running head
    \SetCenterHeads{}%
  }
  \ChapterSpace
  \section*{\centering CHAPTER #1}
  \subsection*{\centering\normalfont\small #2}

macros.\\Part:
%
  \FlushRunningHeads
  \InitRunningHeads
  % Cross-referencing
  \BookMark{0}{Part #1}
  \addtocontents{toc}{\protect\SectTitle{PART #1}}
  \addtocontents{toc}{\protect\SubsectTitle[\protect\footnotesize]{\MakeUppercase{#2}}}
  % Page heading
  \setboolean{ChapterClear}{false}% Tell \Chapter not to start of a new page
  \ifthenelse{\equal{#1}{I.}}{% Special heading for Part I.
    \begin{center}
      \BookHead
    \end{center}
  }{}% Part II., etc.
  \SectTitle{PART #1}
  \SubsectTitle{#2}

macros.\\Chapter:
%
  % Start on a new page unless we've just started a \Part
  \ifthenelse{\boolean{ChapterClear}}{%
    \FlushRunningHeads
    \InitRunningHeads
  }{% Else we've just started a part; set flag
    \setboolean{ChapterClear}{true}%
  }
  % ToC entry
  \refstepcounter{ChapNo}%
  \phantomsection\label{chap:\theChapNo}%
  \addtocontents{toc}{\protect\ToCLine{\theChapNo}{#1}{#2}}
  % PDF bookmark and running heads
  \ifthenelse{\equal{}{}}{% No manual running head
    \BookMark{1}{#2}
    \SetRunningHeads{#2}
    \ChapHead{#1}{#2}
  }{% Manual running head
    \BookMark{1}{}
    \SetRunningHeads{}
    \ChapHead{#1}{#2}
  }

macros.\\Appendix:
%
  \FlushRunningHeads
  \InitRunningHeads
  % ToC entry
  \refstepcounter{ChapNo}%
  \phantomsection\label{chap:\theChapNo}%
  \ifthenelse{\equal{#1}{Catalogue}}{%
    \addtocontents{toc}{\protect\ToCLine{\theChapNo}{}{Catalogue of the Author's Papers on Thermodynamics}}
  }{%
    \addtocontents{toc}{\protect\ToCLine{\theChapNo}{}{#1}}
  }
  % PDF bookmark
  \BookMark{0}{#1}
  \SetRunningHeads{#1}
  \SectTitle{\MakeUppercase{#1}}

